-- Rifts World Book 36: Sovietski - new and revised skills, printed pp.87-90.
-- 7 skills rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~379-sovietski-skills.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.

INSERT OR IGNORE INTO skills (name, category, base, base_formula, per_level, systems, source, source_book, note, bonuses, level_bonuses) VALUES
  ('Contacts - Social Connections', 'Communications', 10, NULL, 2, '["rifts"]', 'import', 'Rifts World Book 36: Sovietski p.87-88', 'Communications or Rogue skill. Two figures, 10%/6% +2% a level. The first is the chance the character has heard of a given person; a roll under one tenth of it means he knows that person himself. The second, 6%, is the chance a known contact both can and will help. Also links objects to the people known for them. Situational modifiers stack: same city +3%, same home town or war camp +8%, same religious enclave +5%, both Party members +3%, same O.C.C. +3%, character is an officer +5%, outranks the contact +5%, P.B. 16+ +5%, M.A. 16+ +5%, asked while drunk +5%; treasonous request -20%, helping a foreigner -5%, helping a D-Bee -5%, a stay of execution -15%, freeing someone the police hold for a minor crime -10%, asking a superior -5%. With M.A. 16 or more it may be taken twice to double the base, and taken again to cover another career or another Russian city, town or camp.', NULL, NULL),
  ('Ballet', 'Physical', 0, NULL, 0, '["rifts"]', 'import', 'Rifts World Book 36: Sovietski p.88', 'Semi-professional training at a top Russian studio. Needs the Dance skill and no bionics. No percentage of its own: it rolls the Dance skill, which gains +15% for ballet only. Also +1D6 S.D.C. (a roll, so kept here). Taken twice, the dancing is of professional standard.', '{"attributes":{"PP":1,"PS":1}}', NULL),
  ('Biathlon', 'Physical', 0, NULL, 0, '["rifts"]', 'import', 'Rifts World Book 36: Sovietski p.88', 'The winter event pairing cross-country skiing with rifle shooting at two to four stations. Needs the Skiing skill and W.P. Rifle. No percentage of its own. Grants +2D6 S.D.C., +1 on initiative only with a rifle, and +5% to Land Navigation; none is stored as a bonus, being a roll or conditional.', NULL, NULL),
  ('Ice Skating (Sovietski)', 'Physical', 35, NULL, 5, '["rifts"]', 'import', 'Rifts World Book 36: Sovietski p.88-89', 'This book''s revision of Ice Skating (the Canada book''s row of that name grants +1 P.E., which this printing does not). Moving on skates is as easy as on the ground, at twice running speed for half the effort, and walking on ice costs half the usual penalties even without skates. Roll to start out on ice, for a stop, leap, trick or combat move, or above 80% of top speed; a failure is a fall for 1D4 S.D.C., two melee actions to rise and a roll to go on. Roller skates work too. Grants +1D4 Spd and +1D6 S.D.C. On ice: +1 dodge, -1 strike, parry, disarm and entangle, and trick or combat moves roll at -30%. Pro specialties take the skill a second time, one only, as an O.C.C. Related pick (an unstated trick is -20%): Figure +20%, three times running speed; Hockey +15%, fights on ice without the penalty, three times running speed; Speed +10%, five times running speed. Each adds its own attribute, S.D.C. and combat bonuses.', NULL, NULL),
  ('Skiing and Snowboarding', 'Physical', 40, NULL, 5, '["rifts"]', 'import', 'Rifts World Book 36: Sovietski p.89', 'This book''s revision of skiing; Snow Skiing is the Canada book''s version. Covers downhill and cross-country (at Spd) on skis, or a snowboard, which cannot go cross-country. Roll to set off, for a stop, swerve, jump or combat action, or above 80% of top speed; a failure is a fall, lost initiative and two actions, and 1D6 S.D.C., then two actions to rise and a roll to go on. Also +1D6 S.D.C. On skis there is no snow speed penalty, but combat bonuses are halved and trick or combat moves roll at -30%. Pro specialties each cost one more O.C.C. Related pick and may be taken more than once (an unstated trick is -20%): Downhill/Slalom +15%, up to 70 mph; Cross-Country +10%, 20% over running speed, skis only, risky past 20 mph; Snowboarding and Jump Skiing +20%, tricks at -10%, jumps to 300 ft, a crash is 2D6 H.P./S.D.C. Each adds its own attribute, S.D.C. and combat bonuses.', '{"attributes":{"PE":1}}', NULL),
  ('Kremlinology', 'Technical', 0, NULL, 0, '["rifts"]', 'import', 'Rifts World Book 36: Sovietski p.90', 'Study of Soviet politics, policy and cultural history: how the army and the Party interlock and how to work that system, and how to sway the politically minded with the right references and quotations. No percentage of its own. Grants, only where the Sovietski are concerned: +5% Contacts - Social Connections, +5% Public Speaking, +10% Law (General), +5% History (Pre-Rifts) and +10% History (Post-Apocalypse).', NULL, NULL),
  ('Law: Loopholes', 'Technical', 20, NULL, 4, '["rifts"]', 'import', 'Rifts World Book 36: Sovietski p.90', 'Printed as Law - Loopholes. Needs Law (General). Knowledge of the exemptions, special categories and vague wording in one country''s or region''s local, regional and national codes (for example the NGR, or Russia with its Sovietski and Warlord camps), used to make an act legal on a technicality. Success is no shield: the gap may be closed, a better lawyer may answer it, or the authorities may act outside the law.', NULL, NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 7 skills rows are in' AS assertion, count(*) AS got, 7 AS want
  FROM skills WHERE name IN ('Contacts - Social Connections', 'Ballet', 'Biathlon', 'Ice Skating (Sovietski)', 'Skiing and Snowboarding', 'Kremlinology', 'Law: Loopholes') AND source_book IS NOT NULL;

